/*
 * indeterminate-checkbox. It draws itself in, then its window becomes checkbox-blank's: the outline flows into the other drawing's,
 * holds, and flows back. Bring the pointer near and it turns toward the other.
 * Generated by dogfood/hard/generate.py from the owner's story (dogfood/HARD.md); measured, not read off by eye.
 */
const { icon, spring, stepS, register, pointer, disposer, story, clamp, smooth, SPRING } = IF;

function mount({ stage, svg, read, src }, reach) {
  const bag = disposer();
  const ic = icon(svg, src);
  const [opening] = ic.hole(0);
  const front = ic.part("front", [0], { paint: "first" });
  ic.part("side", [2]);
  const win = ic.part("window", [opening, 1]);
  win.hi(true);
  const S = front.extent("u-up"), W = win.extent("u-up");
  /* checkbox-blank's window, as fractions of its own screen (measured with the kernel), placed on this screen */
  const OTHER = [[0.889, 0.1111], [0.8631, 0.1111], [0.8373, 0.1111], [0.8114, 0.1111], [0.7856, 0.1111], [0.7597, 0.1111], [0.7339, 0.1111], [0.7081, 0.1111], [0.6822, 0.1111], [0.6564, 0.1111], [0.6305, 0.1111], [0.6047, 0.1111], [0.5788, 0.1111], [0.553, 0.1112], [0.5271, 0.1112], [0.5013, 0.1112], [0.4755, 0.1112], [0.4496, 0.1112], [0.4238, 0.1112], [0.3979, 0.1112], [0.3721, 0.1112], [0.3462, 0.1112], [0.3204, 0.1112], [0.2945, 0.1112], [0.2687, 0.1112], [0.2429, 0.1112], [0.217, 0.1112], [0.1912, 0.1112], [0.1653, 0.1112], [0.1395, 0.1112], [0.1136, 0.1112], [0.1112, 0.1347], [0.1112, 0.1607], [0.1112, 0.1867], [0.1112, 0.2127], [0.1112, 0.2387], [0.1112, 0.2647], [0.1112, 0.2907], [0.1112, 0.3168], [0.1112, 0.3428], [0.1112, 0.3688], [0.1112, 0.3948], [0.1112, 0.4208], [0.1112, 0.4468], [0.1112, 0.4728], [0.1112, 0.4988], [0.1112, 0.5248], [0.1112, 0.5508], [0.1112, 0.5768], [0.1112, 0.6028], [0.1112, 0.6288], [0.1112, 0.6548], [0.1112, 0.6808], [0.1112, 0.7069], [0.1112, 0.7329], [0.1112, 0.7589], [0.1112, 0.7849], [0.1112, 0.8109], [0.1112, 0.8369], [0.1112, 0.8629], [0.1112, 0.8889], [0.1371, 0.8889], [0.1629, 0.8889], [0.1888, 0.8889], [0.2146, 0.8889], [0.2405, 0.8889], [0.2663, 0.8889], [0.2922, 0.8889], [0.318, 0.8889], [0.3439, 0.8889], [0.3697, 0.8889], [0.3956, 0.889], [0.4214, 0.889], [0.4472, 0.889], [0.4731, 0.889], [0.4989, 0.889], [0.5248, 0.889], [0.5506, 0.889], [0.5765, 0.889], [0.6023, 0.889], [0.6282, 0.889], [0.654, 0.889], [0.6799, 0.889], [0.7057, 0.889], [0.7315, 0.889], [0.7574, 0.889], [0.7832, 0.889], [0.8091, 0.889], [0.8349, 0.889], [0.8608, 0.889], [0.8866, 0.889], [0.889, 0.8653], [0.889, 0.8393], [0.889, 0.8133], [0.889, 0.7873], [0.889, 0.7613], [0.889, 0.7353], [0.889, 0.7093], [0.889, 0.6833], [0.889, 0.6573], [0.889, 0.6313], [0.889, 0.6053], [0.889, 0.5792], [0.889, 0.5532], [0.889, 0.5272], [0.889, 0.5012], [0.889, 0.4752], [0.889, 0.4492], [0.889, 0.4232], [0.889, 0.3972], [0.889, 0.3712], [0.889, 0.3452], [0.889, 0.3192], [0.889, 0.2932], [0.889, 0.2672], [0.889, 0.2412], [0.889, 0.2152], [0.889, 0.1892], [0.889, 0.1631], [0.889, 0.1371]];
  const target = OTHER.map(([fa, fb]) => S.pt(S.a[0] + fa * (S.a[1] - S.a[0]), S.b[0] + fb * (S.b[1] - S.b[0])));
  const shape = ic.morph(opening, target, { hide: [1] }); // its inner wall belongs to its own outline
  const life = story(stage, {
    rest: { become: 0, ink: 1 },
    poster: { become: 1, ink: 1 },
    intro: { dur: 3000, from: { ink: 0 }, ease: "linear" },
    beats: [
      { dur: 1000 },
      { dur: 900, to: { become: 1 } },  // it becomes the other
      { dur: 1500 },
      { dur: 900, to: { become: 0 } },  // and itself again
      { dur: 900 },
    ],
  });
  const hand = spring(0, SPRING.hand);
  let max = reach, label = "";
  const centre = W.pt((W.a[0] + W.a[1]) / 2, (W.b[0] + W.b[1]) / 2);
  const loop = register(stage, (dt) => {
    const x = life.step(dt), y = stepS(hand, dt);
    const v = life.values(life.held ? { become: hand.x } : {});
    ic.ink(v.ink);
    const t = v.become * max;
    shape.set(t);
    const shown = v.ink < 1 ? "drawing" : t < 0.02 ? "rest" : `square ${Math.round(t * 100)}%`;
    if (shown !== label) { read.textContent = shown; label = shown; }
    return x || y;
  });
  const leave = () => { life.hold(false); loop.wake(); };
  bag.add(pointer(stage, {
    move(pt) {
      const near = 1 - smooth(30, 170, Math.hypot(pt[0] - centre[0], pt[1] - centre[1]));
      if (near <= 0) { leave(); return; }
      if (!life.held) { hand.x = life.values().become; life.hold(true); }
      hand.t = near;
      loop.wake();
    },
    leave,
  }));
  bag.add(() => { loop.unregister(); while (svg.firstChild) svg.firstChild.remove(); });
  return { set(v) { max = clamp(v, 0, 1); loop.wake(); }, destroy: bag.dispose };
}

isoform({
  name: "indeterminate-checkbox",
  icon: "indeterminate-checkbox",
  variant: "rounded-left",
  means: "Its window flows into checkbox-blank's outline, holds, and flows back.",
  rules: [5, 8, 9],
  range: [0.6, 0.85, 1],
  mount,
});
